import { test, expect } from "@playwright/test";
import { mkdir, mkdtemp, writeFile } from "node:fs/promises";
import { join, resolve } from "node:path";
import { configuration, createService, startServer } from "../../server.mjs";

let server, service, workspace, source;
test.beforeAll(async () => {
  if (!process.env.NIXTLA_E2E_OUTPUT) throw new Error("Set NIXTLA_E2E_OUTPUT to an explicit disposable artifact directory.");
  await mkdir(process.env.NIXTLA_E2E_OUTPUT, { recursive: true });
  workspace = await mkdtemp(join(resolve(process.env.NIXTLA_E2E_OUTPUT), "journey-"));
  source = join(workspace, "synthetic-revenue.csv");
  const rows = ["unique_id,ds,y"];
  for (let i = 0; i < 60; i++) rows.push(`Synthetic revenue,${2020 + Math.floor(i / 12)}-${String(i % 12 + 1).padStart(2, "0")}-01,${100 + i * 2 + Math.round(Math.sin(i * Math.PI / 6) * 15)}`);
  await writeFile(source, rows.join("\n"));
  const { runtime, contract } = await configuration();
  service = createService({ workspace, python: runtime.python, contract });
  server = await startServer({ workspace, service, handoff: async () => {} });
});
test.afterAll(async () => { await server?.close(); await service?.close(); });

test("profile, forecast, replay, persistent drafts and responsive themes", async ({ page }) => {
  const errors = [];
  page.on("pageerror", error => errors.push(error.message));
  await page.goto(server.url);
  await expect(page.getByRole("button", { name: "Create local workspace" })).toBeVisible();
  expect((await service.call("catalog")).jobs).toHaveLength(0);
  await page.getByRole("button", { name: "Create local workspace" }).click();
  await page.getByLabel("Local CSV or saved-value workbook").fill(source);
  await page.getByLabel("Forecast horizon", { exact: true }).fill("3");
  await page.getByLabel("Model policy", { exact: true }).selectOption("baseline");
  await page.getByRole("button", { name: "Analyze & forecast" }).click();
  await expect(page.getByRole("heading", { name: "What the data says" })).toBeVisible();
  await expect(page.getByRole("button", { name: "Open forecast" }).first()).toBeVisible({ timeout: 120000 });
  await page.getByRole("button", { name: "Open forecast" }).first().click();
  await expect(page.getByRole("heading", { name: "Actuals and forecast" })).toBeVisible();
  await expect(page.getByRole("alert")).toHaveCount(0);
  const beforeEvidence = (await service.call("catalog")).jobs.length;
  await page.getByRole("button", { name: "Models", exact: true }).click();
  await page.getByText("Fitted recipes and failed attempts", { exact: true }).click();
  const fitted = page.getByRole("region", { name: "Actual fitted candidates", exact: true });
  await expect(fitted.locator("tbody tr").first()).toBeVisible();
  await expect(fitted).toContainText("succeeded");
  await expect(fitted.getByRole("columnheader", { name: "constructor", exact: true })).toBeVisible();
  expect((await service.call("catalog")).jobs).toHaveLength(beforeEvidence);
  await page.getByRole("button", { name: "Forecast", exact: true }).click();
  await page.screenshot({ path: join(workspace, "forecast-light.png") });
  await page.getByRole("button", { name: "Compare", exact: true }).click();
  await expect(page.getByRole("heading", { name: "Replay a forecast origin" })).toBeVisible();
  const selector = page.getByLabel("Comparison evidence");
  await selector.selectOption({ index: 1 });
  await expect(page.getByRole("columnheader", { name: "weights", exact: true })).toBeVisible();
  await expect(page.getByRole("button", { name: "Adopt directional version", exact: true })).toBeVisible();
  await page.screenshot({ path: join(workspace, "ensemble-replay.png") });
  await page.getByRole("button", { name: "New tab", exact: true }).click();
  await expect(page.locator(".document-tab")).toHaveCount(2);
  await page.getByRole("button", { name: "Research", exact: true }).click();
  await expect(page.getByLabel("Finding or decision")).toBeVisible();
  await page.getByLabel("Finding or decision").fill("A draft survives reload and close.");
  await expect(page.getByRole("status").filter({ hasText: "Saved locally" })).toBeVisible();
  await page.reload();
  await expect(page.getByLabel("Finding or decision")).toHaveValue("A draft survives reload and close.");
  await page.locator(".document-tab.active .tab-close").click();
  await page.getByRole("button", { name: /^Recently closed/ }).click();
  await page.getByRole("button", { name: /^Reopen draft:/ }).first().click();
  await expect(page.getByLabel("Finding or decision")).toHaveValue("A draft survives reload and close.");
  await page.getByRole("button", { name: "Compare", exact: true }).click();
  await page.getByRole("button", { name: "Adopt directional version", exact: true }).click();
  await expect(page.getByRole("dialog")).toContainText("not a promotion");
  await page.getByRole("button", { name: "Approve new directional version", exact: true }).click();
  await expect.poll(async () => (await service.call("catalog")).jobs.find(job => job.kind === "adopt")?.status, { timeout: 90000 }).toBe("completed");
  await expect(page.locator(".activity-strip > div").filter({ hasText: /adopt/i })).toContainText("completed");
  await page.locator(".activity-strip > div").filter({ hasText: /adopt/i }).getByRole("button", { name: "Open forecast" }).click();
  await expect(page.getByRole("heading", { name: "Actuals and forecast" })).toBeVisible();
  await page.getByRole("button", { name: "Compare", exact: true }).click();
  await page.getByRole("button", { name: "Version changes", exact: true }).click();
  await page.getByLabel("Reference version").selectOption({ index: 1 });
  await expect(page.getByRole("heading", { name: "Exact version deltas" })).toBeVisible();
  await page.getByRole("button", { name: "Forecast", exact: true }).click();
  await expect(page.getByRole("heading", { name: "Actuals and forecast" })).toBeVisible();
  await page.getByLabel("Appearance").selectOption("dark");
  await page.screenshot({ path: join(workspace, "forecast-dark.png") });
  await page.setViewportSize({ width: 620, height: 900 });
  await page.getByRole("button", { name: "Toggle library", exact: true }).click();
  await page.screenshot({ path: join(workspace, "forecast-narrow.png") });
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
  expect(errors).toEqual([]);
  console.log(`Rendered evidence: ${workspace}`);
});

test("loopback boundary rejects unauthorized calls and unlisted assets", async ({ request }) => {
  const origin = new URL(server.url).origin;
  expect((await request.post(`${origin}/api`, { data: { operation: "catalog", input: {} } })).status()).toBe(403);
  expect((await request.get(`${origin}/server.mjs`)).status()).toBe(404);
});

test("actuals, frozen refresh, reviewed extraction and keyboard recovery stay in one workspace", async ({ page }) => {
  test.setTimeout(240000);
  const catalog = await service.call("catalog");
  const adopted = catalog.runs.find(run => run.metadata.adopted);
  expect(adopted).toBeTruthy();
  await service.call("save_state", { expectedRevision: catalog.revision, state: {
    documents: [{ id: "operations", runId: adopted.id, title: "Synthetic operations", series: "Synthetic revenue", view: "Pipeline" }],
    activeId: "operations", theme: "light",
  } });
  await page.goto(server.url);
  await page.getByLabel("Maintenance operation").selectOption("actuals");
  await page.getByText("Inspect a new local source", { exact: true }).click();
  const actuals = join(workspace, "actuals.csv");
  await writeFile(actuals, "unique_id,ds,y\nSynthetic revenue,2025-01-01,222\nSynthetic revenue,2025-02-01,229\nSynthetic revenue,2025-03-01,234\n");
  await page.getByLabel("Maintenance source file").fill(actuals);
  await page.getByRole("button", { name: "Inspect new snapshot", exact: true }).click();
  await page.getByLabel("Actuals known as of").fill("2025-04-01T00:00:00Z");
  await page.getByRole("button", { name: "Review actuals import", exact: true }).click();
  await expect(page.getByLabel("Actuals known as of")).toHaveValue("2025-04-01T00:00:00Z");
  await page.getByRole("button", { name: "Approve actuals", exact: true }).click();
  await expect(page.getByRole("dialog")).toHaveCount(0);
  await expect(page.getByRole("alert")).toHaveCount(0);
  await expect.poll(async () => (await service.call("catalog")).jobs.find(job => job.kind === "actuals")?.status, { timeout: 90000 }).toBe("completed");
  await expect(page.getByRole("region", { name: "Ledger values" })).toContainText("3 rows shown");
  await expect(page.getByLabel("Maintenance source file")).toBeVisible();
  await expect(page.getByLabel("Maintenance source file")).toHaveValue(actuals);
  await page.getByRole("button", { name: "Close inspector", exact: true }).click();

  await page.getByLabel("Maintenance operation").selectOption("refresh");
  const refreshed = join(workspace, "refreshed.csv");
  const rows = ["unique_id,ds,y"];
  for (let i = 0; i < 63; i++) rows.push(`Synthetic revenue,${2020 + Math.floor(i / 12)}-${String(i % 12 + 1).padStart(2, "0")}-01,${100 + i * 2 + Math.round(Math.sin(i * Math.PI / 6) * 15)}`);
  await writeFile(refreshed, rows.join("\n"));
  await page.getByLabel("Maintenance source file").fill(refreshed);
  await page.getByRole("button", { name: "Inspect new snapshot", exact: true }).click();
  await page.getByRole("button", { name: "Review refresh", exact: true }).click();
  await expect(page.getByRole("dialog")).toContainText("Frozen blends refit");
  await page.getByRole("button", { name: "Approve refresh", exact: true }).click();
  await expect.poll(async () => (await service.call("catalog")).jobs.find(job => job.kind === "refresh")?.status, { timeout: 120000 }).toBe("completed");
  const updated = (await service.call("catalog")).jobs.find(job => job.kind === "refresh");
  const forecast = await service.call("view", { runId: updated.result.runId });
  expect(forecast.rows.every(row => row.model === "Blend")).toBe(true);
  expect(forecast.run.metadata.parentRunId).toBe(adopted.id);

  const script = join(workspace, "extract.py");
  await writeFile(script, "import sys\nfrom pathlib import Path\np=Path(sys.argv[1]); p.parent.mkdir(parents=True,exist_ok=True)\np.write_text('unique_id,ds,y\\nSynthetic revenue,2025-01-01,222\\nSynthetic revenue,2025-02-01,229\\nSynthetic revenue,2025-03-01,234\\n')\n");
  await page.getByText("Author or refresh a source pipeline", { exact: true }).click();
  await page.getByLabel("Pipeline extract script").fill(script);
  await page.getByLabel("Extract only; inspect the new source before modeling").check();
  const before = (await service.call("catalog")).jobs.length;
  await page.getByRole("button", { name: "Review pipeline execution", exact: true }).click();
  await expect(page.getByRole("dialog")).toContainText("not a sandbox");
  expect((await service.call("catalog")).jobs.length).toBe(before);
  await page.getByRole("button", { name: "Approve reviewed pipeline", exact: true }).click();
  await expect.poll(async () => (await service.call("catalog")).jobs.find(job => job.kind === "pipeline")?.status, { timeout: 90000 }).toBe("completed");

  await page.getByLabel("Maintenance operation").selectOption("lock");
  await page.getByLabel("Revision or lock label").fill("Synthetic plan");
  await expect(page.getByRole("button", { name: "Review official lock" })).toBeDisabled();
  await expect(page.getByText("This version's saved gate does not permit a planning lock.", { exact: false })).toBeVisible();
  await page.getByRole("button", { name: "Ask Copilot", exact: true }).click();
  await expect(page.getByRole("dialog")).toBeVisible();
  await page.keyboard.press("Escape");
  await expect(page.getByRole("dialog")).toHaveCount(0);
  await expect(page.getByRole("button", { name: "Ask Copilot", exact: true })).toBeFocused();
  await page.emulateMedia({ reducedMotion: "reduce" });
  await page.setViewportSize({ width: 620, height: 900 });
  if (await page.getByRole("button", { name: "Close inspector", exact: true }).isVisible()) await page.getByRole("button", { name: "Close inspector", exact: true }).click();
  await page.getByRole("button", { name: "Toggle library", exact: true }).click();
  await page.getByRole("heading", { name: "Maintain this forecast", exact: true }).scrollIntoViewIfNeeded();
  await page.screenshot({ path: join(workspace, "maintenance-narrow.png") });
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
});
